class SpaceCraft {
  constructor(name, fuelCapacity) {
    this.name = name;
    this.fuelCapacity = fuelCapacity;
    // TODO: Initialize a private field #fuelLevel to fuelCapacity
  }

  launch() {
    if (this.#fuelLevel < 10) { // Assume 10 units of fuel needed to launch
      return `${this.name} needs more fuel to launch! Current fuel: ${this.#fuelLevel}`;
    }
    this.#fuelLevel -= 10;
    return `${this.name} launched successfully! Remaining fuel: ${this.#fuelLevel}`;
  }

  // TODO: Implement a refuel(amount) method
  // It should increase #fuelLevel, ensuring it doesn't exceed fuelCapacity
}

class FighterJet extends SpaceCraft {
  constructor(name, fuelCapacity, weaponSystem) {
    // TODO: Call the parent constructor with name and fuelCapacity
    this.weaponSystem = weaponSystem;
  }

  attack() {
    return `${this.name} engaging target with ${this.weaponSystem}!`
  }
}

class CargoShip extends SpaceCraft {
  constructor(name, fuelCapacity, cargoCapacity) {
    // TODO: Call the parent constructor with name and fuelCapacity
    this.cargoCapacity = cargoCapacity;
    this.currentCargo = 0;
  }

  loadCargo(amount) {
    if (this.currentCargo + amount > this.cargoCapacity) {
      return `${this.name} cannot load ${amount} units. Cargo capacity exceeded!`
    }
    this.currentCargo += amount;
    return `${this.name} loaded ${amount} units of cargo. Total cargo: ${this.currentCargo}/${this.cargoCapacity}`;
  }
}

